<?php
$where=[];$params=[];$query=trim((string)($_GET['import_q']??''));if($query!==''){$query=substr($query,0,200);$where[]='(b.filename LIKE ? OR b.result_json LIKE ? OR b.error_json LIKE ? OR u.name LIKE ?)';$params=array_fill(0,4,'%'.$query.'%');}
foreach(['import_status'=>'status','import_type'=>'import_type','platform'=>'platform'] as $key=>$column)if(!empty($_GET[$key])){$where[]='b.'.$column.'=?';$params[]=$_GET[$key];}
foreach(['date_from'=>'>=','date_to'=>'<='] as $key=>$op)if(preg_match('/^\d{4}-\d{2}-\d{2}$/D',$_GET[$key]??'')){$where[]='DATE(b.created_at)'.$op.'?';$params[]=$_GET[$key];}
$sql=' FROM import_batches b LEFT JOIN users u ON u.id=b.user_id'.($where?' WHERE '.implode(' AND ',$where):'');$stmt=db()->prepare('SELECT COUNT(*)'.$sql);$stmt->execute($params);$total=(int)$stmt->fetchColumn();$all=($_GET['history']??'')==='all';$limit=$all?50:10;$offset=$all?max(0,(int)($_GET['offset']??0)):0;
echo '<div class="page-head"><div><h1>Import History</h1><p>Search uploads, review unresolved rows and open the original order review before submitting.</p></div></div><div class="card"><form method="get" class="inflow-search-form"><input type="hidden" name="page" value="imports"><input type="hidden" name="history" value="all"><label>Search<input name="import_q" maxlength="200" value="'.e($query).'" placeholder="File, Order ID, product, staff, error..."></label><label>From<input type="date" name="date_from" value="'.e($_GET['date_from']??'').'"></label><label>To<input type="date" name="date_to" value="'.e($_GET['date_to']??'').'"></label><label>Platform<select name="platform"><option value="">All platforms</option>';foreach(['Shopee','Lazada','TikTok'] as $v)echo '<option '.(($_GET['platform']??'')===$v?'selected':'').'>'.$v.'</option>';echo '</select></label><label>Status<select name="import_status"><option value="">All statuses</option>';foreach(['Review','Unsuccessful','Confirmed','Complete','Incomplete','Cancelled','Reversed'] as $v)echo '<option value="'.$v.'" '.(($_GET['import_status']??'')===$v?'selected':'').'>'.e($v).'</option>';echo '</select></label><button class="btn secondary">Search</button><a class="btn ghost" href="?page=imports">Clear Filters</a></form></div>';
$link=function($changes){return '?'.http_build_query(array_replace($_GET,['page'=>'imports'], $changes));};echo '<div class="modal-actions"><span>'.($all?($total?($offset+1).'–'.min($total,$offset+$limit).' of '.$total:'No matching uploads'):'Latest 10 uploads').'</span><a class="btn ghost" href="'.e($link(['history'=>$all?'':'all','offset'=>0])).'">'.($all?'Recent':'View all').'</a>';if($all&&$offset)echo '<a class="btn ghost" href="'.e($link(['offset'=>max(0,$offset-50)])).'">Previous</a>';if($all&&$offset+50<$total)echo '<a class="btn ghost" href="'.e($link(['offset'=>$offset+50])).'">Next</a>';echo '</div><div class="card table-wrap"><table class="table"><tr><th>Date / File</th><th>Type / Platform</th><th>Processed By</th><th>Rows</th><th>Posted / Duplicates</th><th>Unresolved</th><th>Status</th><th>Review</th></tr>';
$stmt=db()->prepare('SELECT b.*,u.name'.$sql.' ORDER BY b.id DESC LIMIT '.$limit.' OFFSET '.$offset);$stmt->execute($params);foreach($stmt as $r){$dest=$r['import_type']==='Orders'?'order_review':'import_detail';$status=$r['status']?:'Legacy record';$meta=json_decode($r['result_json']??'[]',true)?:[];if($status==='Complete'&&!empty($meta['stock_warnings']))$status='Posted with Warnings';echo '<tr><td>'.e(substr($r['created_at'],0,16)).'<br>'.e($r['filename']).'</td><td>'.e($r['import_type']).'<br>'.platform_label($r['platform']?:'—').'</td><td>'.e($r['name']).'</td><td>'.(int)$r['rows_read'].'</td><td>'.(int)$r['imported_count'].' posted<br>'.(int)$r['duplicate_count'].' skipped</td><td>'.(int)$r['error_count'].' errors<br>'.(int)$r['unmapped_count'].' unmatched</td><td>'.badge($r['import_type']==='Beginning Balance'?beginning_status_label($status):$status,status_badge_class($status)).'</td><td><a class="btn ghost" href="?page='.$dest.'&id='.$r['id'].'">View / Review</a></td></tr>';}echo '</table></div>';
